// Warn in development when a human-type avatar renders an image with no description.
//
// Scope and edge semantics (settled in spec 126, option O2):
// - Human type only. Agent type ignores `src` entirely (Req 5 AC 5), so there is no
//   image to describe and nothing to warn about.
// - `decorative` exempts. It is the official "this image is non-informative" signal
//   (Req 9.2, rendered as aria-hidden), so demanding alt text there is a false positive.
// - `alt == null` (absent), not `!alt`. A raw `setAttribute('alt', '')` is an explicit
//   empty description and stays silent. Note the `alt` setter removes the attribute on a
//   falsy value, so the property form `avatar.alt = ''` collapses to absent and warns.
//
// @see Requirements: 5.4 (human + src requires alt), 5 AC 5 (agent ignores src), 9.2
if (type === 'human' && src && alt == null && !decorative && typeof console !== 'undefined') {
  console.warn(
    'AvatarBaseElement: "alt" is required when "src" is provided. ' +
    'Add an alt description of the image; or, if this avatar is purely decorative ' +
    '(non-informative), set the "decorative" prop to hide it from screen readers.'
  );
}

